import { cn } from '@cascivo/core/pure'
import type { HTMLAttributes } from 'react'
import styles from './progress-circle.module.css'

const RADIUS = 20
const CIRCUMFERENCE = 2 * Math.PI * RADIUS

export interface ProgressCircleProps extends HTMLAttributes<HTMLDivElement> {
  /** Current value from 0 to max — clamped. */
  value: number
  /**
   * Maximum allowed value.
   *
   * @defaultValue `100`
   * @see the component manifest
   */
  max?: number
  size?: 'sm' | 'md' | 'lg'
  /**
   * Renders the rounded percentage in the center — pairs best with md and lg
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  showValue?: boolean
  /** Accessible name for the progressbar. */
  label?: string
  /**
   * Alias of `label` — the same invisible accessible name under the catalog's own spelling.
   *
   * `ariaLabel` is what the catalog calls a name nothing paints, so it is the guess an agent
   * makes after reading one other component (2026-08-21 report item 1). This component
   * predates the convention and shipped `label`; both work and neither is deprecated.
   */
  ariaLabel?: string
}

export function ProgressCircle({
  value,
  max = 100,
  size = 'md',
  showValue = false,
  label,
  ariaLabel,
  className,
  ...props
}: ProgressCircleProps) {
  const clamped = Math.min(Math.max(value, 0), max)
  const percent = max > 0 ? (clamped / max) * 100 : 0
  const offset = CIRCUMFERENCE * (1 - percent / 100)

  return (
    <div
      role="progressbar"
      aria-valuemin={0}
      aria-valuemax={max}
      aria-valuenow={clamped}
      aria-label={ariaLabel ?? label}
      data-size={size}
      className={cn(styles['progressCircle'], className as string | undefined)}
      {...props}
    >
      <svg viewBox="0 0 48 48" aria-hidden="true" className={styles['svg']}>
        <circle
          className={styles['track']}
          cx="24"
          cy="24"
          r={RADIUS}
          fill="none"
          strokeWidth="4"
        />
        <circle
          className={styles['fill']}
          cx="24"
          cy="24"
          r={RADIUS}
          fill="none"
          strokeWidth="4"
          strokeLinecap="round"
          strokeDasharray={CIRCUMFERENCE}
          strokeDashoffset={offset}
        />
      </svg>
      {showValue && <span className={styles['value']}>{Math.round(percent)}%</span>}
    </div>
  )
}

@layer cascivo.component {
  .progressCircle {
    position: relative;
    display: inline-grid;
    place-items: center;

    &[data-size='sm'] {
      inline-size: 1.5rem;
      block-size: 1.5rem;
    }

    &[data-size='md'] {
      inline-size: 2.5rem;
      block-size: 2.5rem;
    }

    &[data-size='lg'] {
      inline-size: 3.5rem;
      block-size: 3.5rem;
    }

    &[data-size='lg'] .value {
      font-size: var(--cascivo-text-sm);
    }
  }

  .svg {
    inline-size: 100%;
    block-size: 100%;
    display: block;
  }

  .track {
    /* A fill, not a rule — the border colour is near-black in the hard-edged themes. Same
       track as Progress. */
    stroke: var(--cascivo-color-surface-2);
  }

  .fill {
    stroke: var(--cascivo-color-accent);
    transform: rotate(-90deg);
    transform-origin: center;
    transition: stroke-dashoffset var(--cascivo-duration-300) var(--cascivo-ease-out);
  }

  .value {
    position: absolute;
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-xs);
    font-weight: var(--cascivo-font-semibold);
    color: var(--cascivo-color-text);
    font-variant-numeric: tabular-nums;
    line-height: 1;
  }

  @media (prefers-reduced-motion: reduce) {
    .fill {
      transition: none;
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'ProgressCircle',
  description: 'Circular determinate progress indicator rendered as an SVG arc',
  category: 'feedback',
  clientJs: 'none',
  states: [],
  variants: [],
  sizes: ['sm', 'md', 'lg'],
  props: [
    {
      name: 'value',
